def _resolve_tasks_root() -> Path:
    raw = os.environ.get("TASKS_ROOT", str(Path.cwd() / "tasks"))
    candidate = Path(raw).expanduser().resolve()
    try:
        candidate.mkdir(parents=True, exist_ok=True)
        probe = candidate / f".write-probe-{uuid.uuid4().hex}"
        probe.write_text("ok", encoding="utf-8")
        probe.unlink()
    except OSError as exc:
        raise RuntimeError(f"TASKS_ROOT {candidate!s} is not writable: {exc}") from exc
    return candidate


TASKS_ROOT = _resolve_tasks_root()


def _resolve_instavm_base_url() -> str:
    raw = (
        os.environ.get("INSTAVM_BASE_URL")
        or os.environ.get("INSTAVM_API_BASE_URL")
        or os.environ.get("INSTAVM_BASE")
        or ""
    )
    raw = raw.strip().rstrip("/")
    parsed = urlparse(raw)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise RuntimeError(f"INSTAVM_BASE_URL must be a valid http(s) URL, got {raw!r}")
    return raw


