def bounded_text(value: Any, max_chars: int = MAX_STEP_OUTPUT_CHARS) -> str:
    text = value if isinstance(value, str) else str(value)
    if max_chars <= 0:
        return ""
    if len(text) <= max_chars:
        return text
    suffix_template = "\n[truncated {n} characters]"
    minimal_suffix = suffix_template.format(n=len(text) - max_chars)
    if len(minimal_suffix) >= max_chars:
        return text[:max_chars]
    keep = max_chars - len(minimal_suffix)
    while True:
        omitted = len(text) - keep
        suffix = suffix_template.format(n=omitted)
        if len(suffix) <= max_chars - keep:
            return text[:keep] + suffix
        keep -= 1
        if keep <= 0:
            return text[:max_chars]


_IDENTIFIER_ALLOWED = re.compile(r"[A-Za-z0-9._-]")


def safe_identifier(value: Any, default: str, max_len: int = MAX_IDENTIFIER_LENGTH, lowercase: bool = True) -> str:
    raw = "" if value is None else str(value)
    raw = raw.strip()
    if not raw:
        raw = default
    if lowercase:
        raw = raw.lower()
    out_chars: List[str] = []
    previous_dash = False
    for character in raw:
        if _IDENTIFIER_ALLOWED.match(character):
            out_chars.append(character)
            previous_dash = False
        elif not previous_dash:
            out_chars.append("-")
            previous_dash = True
    result = "".join(out_chars).strip("-._")
    result = re.sub(r"\.{2,}", ".", result)
    if not result:
        result = re.sub(r"[^A-Za-z0-9._-]+", "-", default).strip("-._") or "task"
    if len(result) > max_len:
        digest_suffix = uuid.uuid5(uuid.NAMESPACE_OID, result).hex[:8]
        keep = max(1, max_len - len(digest_suffix) - 1)
        result = f"{result[:keep]}-{digest_suffix}"
    return result


def safe_artifact_name(value: Any, default_stem: str, default_suffix: str, max_len: int = MAX_FILENAME_LENGTH) -> str:
    if value is None:
        raw = f"{default_stem}{default_suffix}"
    else:
        raw = str(value).strip()
        if not raw:
            raw = f"{default_stem}{default_suffix}"
    name = Path(raw).name
    if not name or name in {".", ".."}:
        name = f"{default_stem}{default_suffix}"
    if not re.fullmatch(r"[A-Za-z0-9._-]+", name):
        raise ValidationFailure(
            f"Artifact name {raw!r} contains characters outside [A-Za-z0-9._-]",
            {"value": raw},
        )
    if default_suffix and not name.lower().endswith(default_suffix.lower()):
        name = f"{name}{default_suffix}"
    if len(name) > max_len:
        raise ValidationFailure(
            f"Artifact name {name!r} exceeds maximum length {max_len}",
            {"value": name, "max_len": max_len},
        )
    return name


def json_safe(value: Any, _seen: Optional[set] = None) -> Any:
    if _seen is None:
        _seen = set()
    if isinstance(value, (str, bool)) or value is None:
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            return None
        return value
    object_id = id(value)
    if isinstance(value, (dict, list, tuple, set)):
        if object_id in _seen:
            return "[cyclic-reference]"
        _seen.add(object_id)
        try:
            if isinstance(value, dict):
                out: Dict[str, Any] = {}
                seen_keys: Dict[str, Any] = {}
                for key, item in value.items():
                    key_str = key if isinstance(key, str) else repr(key)
                    if key_str in seen_keys and seen_keys[key_str] is not key:
                        key_str = f"{key_str}#{uuid.uuid4().hex[:6]}"
                    seen_keys[key_str] = key
                    out[key_str] = json_safe(item, _seen)
                return out
            if isinstance(value, list):
                return [json_safe(item, _seen) for item in value]
            if isinstance(value, tuple):
                return {"__type__": "tuple", "items": [json_safe(item, _seen) for item in value]}
            return {"__type__": "set", "items": [json_safe(item, _seen) for item in sorted(value, key=lambda x: repr(x))]}
        finally:
            _seen.discard(object_id)
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Enum):
        return value.value
    if isinstance(value, (bytes, bytearray, memoryview)):
        return {"__type__": "bytes_base64", "value": base64.b64encode(bytes(value)).decode("ascii")}
    if hasattr(value, "model_dump"):
        try:
            return json_safe(value.model_dump(mode="json"), _seen)
        except Exception:
            pass
    if hasattr(value, "dict"):
        try:
            return json_safe(value.dict(), _seen)
        except Exception:
            pass
    try:
        json.dumps(value)
        return value
    except TypeError:
        return {"__type__": "repr", "value": repr(value)}


def model_to_dict(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(mode="json")
    return model.dict()


def canonical_task_id(raw: Optional[str]) -> str:
    if raw is None:
        return uuid.uuid4().hex
    trimmed = str(raw).strip()
    if not trimmed:
        return uuid.uuid4().hex
    candidate = safe_identifier(trimmed, uuid.uuid4().hex, MAX_IDENTIFIER_LENGTH)
    return candidate


def task_dir(task_id: str) -> Path:
    canonical = task_id if task_id else uuid.uuid4().hex
    if not re.fullmatch(r"[A-Za-z0-9._-]+", canonical):
        canonical = safe_identifier(canonical, uuid.uuid4().hex)
    return TASKS_ROOT / canonical


def run_dir(task_id: str, run_id: str) -> Path:
    return task_dir(task_id) / "runs" / run_id


async def _get_task_lock(task_id: str) -> asyncio.Lock:
    async with task_locks_lock:
        lock = task_locks.get(task_id)
        if lock is None:
            lock = asyncio.Lock()
            task_locks[task_id] = lock
        return lock


async def atomic_write_text_async(path: Path, text: str, fsync: bool = True) -> None:
    await asyncio.to_thread(_atomic_write_text_sync, path, text, fsync)


def _atomic_write_text_sync(path: Path, text: str, fsync: bool) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    try:
        fd = os.open(str(temporary_path), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as file:
                file.write(text)
                file.flush()
                if fsync:
                    try:
                        os.fsync(file.fileno())
                    except OSError:
                        pass
        except Exception:
            with contextlib.suppress(OSError):
                os.close(fd)
            raise
        os.replace(temporary_path, path)
        if fsync:
            try:
                dir_fd = os.open(str(path.parent), os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except OSError:
                pass
    finally:
        try:
            if temporary_path.exists():
                temporary_path.unlink()
        except OSError:
            pass


async def atomic_write_json_async(path: Path, data: Any, *, indent: Optional[int] = None, sort_keys: bool = True, fsync: bool = True) -> None:
    serialised = json.dumps(json_safe(data), ensure_ascii=False, indent=indent, sort_keys=sort_keys, allow_nan=False)
    await atomic_write_text_async(path, serialised, fsync=fsync)


async def append_log(task_id: str, run_id: str, message: str) -> None:
    lock = await _get_task_lock(task_id)
    async with lock:
        root = task_dir(task_id)
        await asyncio.to_thread(root.mkdir, parents=True, exist_ok=True)
        log_path = root / "task.log"
        timestamp = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        escaped = message.replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "\\r")
        line = f"{timestamp} run={run_id} {escaped}\n"
        await asyncio.to_thread(_append_text_sync, log_path, line)


def _append_text_sync(path: Path, line: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as file:
        file.write(line)


async def append_task_event(task_id: str, run_id: str, event: Dict[str, Any]) -> None:
    lock = await _get_task_lock(task_id)
    async with lock:
        root = task_dir(task_id)
        await asyncio.to_thread(root.mkdir, parents=True, exist_ok=True)
        path = root / "events.jsonl"
        payload = {
            "time": time.strftime("%Y-%m-%dT%H:%M:%S.%fZ", time.gmtime()),
            "task_id": task_id,
            "run_id": run_id,
            "event": json_safe(event),
        }
        line = json.dumps(payload, ensure_ascii=False, allow_nan=False) + "\n"
        await asyncio.to_thread(_append_text_sync, path, line)


async def persist_task(task_id: str) -> None:
    lock = await _get_task_lock(task_id)
    async with lock:
        async with tasks_store_lock:
            snapshot = json.loads(json.dumps(json_safe(tasks_store.get(task_id, {})), allow_nan=False))
        path = task_dir(task_id) / "task.json"
        await atomic_write_json_async(path, snapshot, indent=2, sort_keys=True)


def _now_iso() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


async def update_task(task_id: str, **updates: Any) -> Dict[str, Any]:
    async with tasks_store_lock:
        existing = tasks_store.setdefault(
            task_id,
            {
                "task_id": task_id,
                "status": TaskStatus.QUEUED.value,
                "phase": TaskPhase.VALIDATION.value,
                "current_step": None,
                "result": None,
                "error": None,
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
                "runs": [],
            },
        )
        for key, value in updates.items():
            if value is None and key == "current_step":
                existing.pop("current_step", None)
                continue
            existing[key] = value
        existing["updated_at"] = _now_iso()
        snapshot = dict(existing)
    await persist_task(task_id)
    return snapshot


async def initialize_task_record(task_id: str, run_id: str) -> Dict[str, Any]:
    async with tasks_store_lock:
        existing = tasks_store.get(task_id)
        if existing is None:
            record = {
                "task_id": task_id,
                "status": TaskStatus.QUEUED.value,
                "phase": TaskPhase.VALIDATION.value,
                "current_step": None,
                "result": None,
                "error": None,
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
                "runs": [{"run_id": run_id, "created_at": _now_iso()}],
            }
            tasks_store[task_id] = record
        else:
            existing.setdefault("runs", []).append({"run_id": run_id, "created_at": _now_iso()})
            existing["status"] = TaskStatus.QUEUED.value
            existing["phase"] = TaskPhase.VALIDATION.value
            existing["result"] = None
            existing["error"] = None
            existing["current_step"] = None
            existing["updated_at"] = _now_iso()
            record = existing
        record_copy = dict(record)
    await persist_task(task_id)
    return record_copy


async def reload_persisted_tasks() -> None:
    if not TASKS_ROOT.exists():
        return
    def _scan() -> List[Tuple[str, Dict[str, Any]]]:
        out: List[Tuple[str, Dict[str, Any]]] = []
        for entry in TASKS_ROOT.iterdir():
            if not entry.is_dir():
                continue
            task_json = entry / "task.json"
            if not task_json.is_file():
                continue
            try:
                data = json.loads(task_json.read_text(encoding="utf-8"))
            except Exception as exc:
                logger.warning("Failed to load persisted task %s: %s", entry.name, exc)
                continue
            if isinstance(data, dict) and "task_id" in data:
                out.append((str(data["task_id"]), data))
        return out
    entries = await asyncio.to_thread(_scan)
    async with tasks_store_lock:
        for task_id, data in entries:
            tasks_store.setdefault(task_id, data)


async def require_api_auth(request: Request) -> None:
    configured_key = _resolve_local_auth_key()
    if not configured_key:
        if REQUIRE_LOCAL_AUTH:
            raise HTTPException(
                status_code=500,
                detail={"code": "auth_misconfigured", "message": "API authentication key is not configured"},
            )
        return
    authorization = request.headers.get("authorization", "")
    provided_key = ""
    invalid_scheme = False
    if authorization:
        parts = authorization.split(None, 1)
        if len(parts) == 2 and parts[0].lower() == "bearer":
            provided_key = parts[1].strip()
        else:
            invalid_scheme = True
    if not provided_key:
        provided_key = request.headers.get("x-api-key", "").strip()
    if not provided_key:
        raise HTTPException(
            status_code=401,
            detail={
                "code": "unauthorized",
                "message": "Missing credentials; expected Bearer token or x-api-key header",
                "authorization_scheme_invalid": invalid_scheme,
            },
        )
    if not _constant_time_eq(provided_key, configured_key):
        raise HTTPException(
            status_code=401,
            detail={
                "code": "unauthorized",
                "message": "Invalid credentials",
                "authorization_scheme_invalid": invalid_scheme,
            },
        )


def _constant_time_eq(left: str, right: str) -> bool:
    if len(left) != len(right):
        return False
    result = 0
    for a, b in zip(left.encode("utf-8"), right.encode("utf-8")):
        result |= a ^ b
    return result == 0


async def _wait_subprocess_with_kill_timeout(proc: asyncio.subprocess.Process) -> None:
    try:
        await asyncio.wait_for(proc.wait(), timeout=SUBPROCESS_KILL_GRACE_SECONDS)
    except asyncio.TimeoutError:
        with contextlib.suppress(ProcessLookupError):
            proc.kill()
        try:
            await asyncio.wait_for(proc.wait(), timeout=SUBPROCESS_KILL_GRACE_SECONDS)
        except asyncio.TimeoutError:
            logger.error("Subprocess %s did not terminate after kill", proc.pid)


async def _kill_subprocess(proc: asyncio.subprocess.Process) -> None:
    if proc.returncode is not None:
        return
    with contextlib.suppress(ProcessLookupError):
        proc.terminate()
    try:
        await asyncio.wait_for(proc.wait(), timeout=SUBPROCESS_KILL_GRACE_SECONDS)
        return
    except asyncio.TimeoutError:
        pass
    with contextlib.suppress(ProcessLookupError):
        proc.kill()
    try:
        await asyncio.wait_for(proc.wait(), timeout=SUBPROCESS_KILL_GRACE_SECONDS)
    except asyncio.TimeoutError:
        logger.error("Subprocess %s did not terminate after kill", proc.pid)


async def run_subprocess(
    cmd: List[str],
    *,
    cwd: Optional[str] = None,
    env: Optional[Dict[str, str]] = None,
    timeout: float = SUBPROCESS_DEFAULT_TIMEOUT_SECONDS,
) -> Tuple[int, bytes, bytes]:
    proc = await asyncio.create_subprocess_exec(
        *cmd,
        cwd=cwd,
        env=env,
        stdout=asyncio.subprocess.PIPE,
        stderr=asyncio.subprocess.PIPE,
    )
    try:
        stdout_bytes, stderr_bytes = await asyncio.wait_for(proc.communicate(), timeout=timeout)
    except asyncio.TimeoutError:
        await _kill_subprocess(proc)
        raise OperationTimeout(
            f"Subprocess timed out after {timeout:.1f}s: {' '.join(shquote(part) for part in cmd)}",
            {"cmd": cmd, "timeout_seconds": timeout},
        )
    except asyncio.CancelledError:
        await _kill_subprocess(proc)
        raise
    return proc.returncode if proc.returncode is not None else -1, stdout_bytes, stderr_bytes


_DOCKER_REF_RE = re.compile(
    r"^(?P<registry>[A-Za-z0-9.\-]+(?::\d+)?)?(?:/)?(?P<repo>[a-z0-9]+(?:(?:[._]|__|[-]+)[a-z0-9]+)*(?:/[a-z0-9]+(?:(?:[._]|__|[-]+)[a-z0-9]+)*)*)(?::(?P<tag>[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}))?(?:@(?P<digest>[A-Za-z][A-Za-z0-9]*(?:[+.-_][A-Za-z][A-Za-z0-9]*)*:[A-Fa-f0-9]{32,}))?$"
)
_DOCKER_TAG_RE = re.compile(r"^[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$")
_DOCKER_REPO_COMPONENT_RE = re.compile(r"^[a-z0-9]+(?:(?:[._]|__|[-]+)[a-z0-9]+)*$")
_REGISTRY_HOST_RE = re.compile(r"^[A-Za-z0-9.\-]+(?::\d+)?$")


def validate_docker_tag(tag: str) -> str:
    if not _DOCKER_TAG_RE.match(tag):
        raise ValidationFailure(f"Invalid Docker tag: {tag!r}", {"value": tag})
    return tag


def validate_docker_repository(name: str) -> str:
    components = name.split("/")
    for component in components:
        if not _DOCKER_REPO_COMPONENT_RE.match(component):
            raise ValidationFailure(
                f"Invalid Docker repository component: {component!r} in {name!r}",
                {"value": name, "component": component},
            )
    return "/".join(components)


def validate_docker_registry(host: str) -> str:
    if not _REGISTRY_HOST_RE.match(host):
        raise ValidationFailure(f"Invalid Docker registry host: {host!r}", {"value": host})
    return host


def validate_full_image_reference(reference: str) -> str:
    if "@" in reference:
        ref_part, digest = reference.split("@", 1)
        if not re.fullmatch(r"[A-Za-z][A-Za-z0-9]*(?:[+.\-_][A-Za-z][A-Za-z0-9]*)*:[A-Fa-f0-9]{32,}", digest):
            raise ValidationFailure(f"Invalid digest in image reference: {reference!r}", {"value": reference})
        reference_without_digest = ref_part
    else:
        reference_without_digest = reference
    if ":" in reference_without_digest.rsplit("/", 1)[-1]:
        repo_part, tag_part = reference_without_digest.rsplit(":", 1)
        validate_docker_tag(tag_part)
    else:
        repo_part = reference_without_digest
    if "/" in repo_part:
        first, rest = repo_part.split("/", 1)
        if "." in first or ":" in first or first == "localhost":
            validate_docker_registry(first)
            validate_docker_repository(rest)
        else:
            validate_docker_repository(repo_part)
    else:
        validate_docker_repository(repo_part)
    return reference


