async def _check_executable_available(name: str) -> None:
    path = await asyncio.to_thread(shutil.which, name)
    if not path:
        raise PreflightError(f"Required executable not found in PATH: {name}", {"executable": name})


async def preflight_environment(push_required: bool) -> None:
    await _check_executable_available("nix")
    await _check_executable_available("docker")
    rc, _stdout, stderr = await run_subprocess(["nix", "--version"], timeout=15.0)
    if rc != 0:
        raise PreflightError("nix --version failed", {"stderr": stderr.decode("utf-8", errors="replace")})
    rc, _stdout, stderr = await run_subprocess(
        ["nix", "show-config", "--extra-experimental-features", "nix-command flakes"],
        timeout=15.0,
    )
    if rc != 0:
        raise PreflightError(
            "Nix flakes feature appears unavailable",
            {"stderr": stderr.decode("utf-8", errors="replace")},
        )
    rc, _stdout, stderr = await run_subprocess(["docker", "version", "--format", "{{json .}}"], timeout=20.0)
    if rc != 0:
        raise PreflightError(
            "Docker daemon is not reachable",
            {"stderr": stderr.decode("utf-8", errors="replace")},
        )
    if push_required:
        rc, stdout, _stderr = await run_subprocess(["docker", "info", "--format", "{{.Username}}"], timeout=15.0)
        if rc != 0:
            raise PreflightError("docker info failed during preflight", {})


def build_snapshot_payload(
    *,
    oci_image: str,
    snapshot_name: str,
    snapshot_type: str,
    vcpu_count: int,
    memory_mb: int,
    build_args_model: Optional[NixBuildArgs],
    envs: Optional[Dict[str, str]],
    post_build_cmd: Optional[str],
    disk_size_gb: Optional[int],
) -> Dict[str, Any]:
    merged_build_args = build_args_model.model_dump(exclude_none=True) if build_args_model else {}
    if envs is not None:
        existing_envs = merged_build_args.get("envs") or {}
        combined = dict(existing_envs)
        for key, value in envs.items():
            combined[str(key)] = str(value)
        if combined:
            merged_build_args["envs"] = combined
    if post_build_cmd is not None and "post_build_cmd" not in merged_build_args:
        merged_build_args["post_build_cmd"] = post_build_cmd
    if disk_size_gb is not None:
        merged_build_args["disk_size_gb"] = int(disk_size_gb)
    payload: Dict[str, Any] = {
        "oci_image": oci_image,
        "name": snapshot_name,
        "vcpu_count": int(vcpu_count),
        "memory_mb": int(memory_mb),
        "type": snapshot_type,
    }
    if merged_build_args:
        payload["build_args"] = merged_build_args
    return payload


async def parse_loaded_image_reference(stdout: str, stderr: str, expected: str) -> Optional[str]:
    candidates: List[str] = []
    pattern_loaded = re.compile(r"Loaded image(?: ID)?:\s*(\S+)", re.IGNORECASE)
    for source in (stdout, stderr):
        for match in pattern_loaded.finditer(source):
            candidates.append(match.group(1).strip())
    expected_lower = expected.lower()
    for candidate in candidates:
        if candidate.lower() == expected_lower:
            return candidate
    if candidates:
        return candidates[0]
    return None


async def fallback_lookup_image(expected: str) -> Optional[str]:
    rc, stdout_bytes, stderr_bytes = await run_subprocess(
        ["docker", "images", "--format", "{{.Repository}}:{{.Tag}}"],
        timeout=60.0,
    )
    stderr_text = stderr_bytes.decode("utf-8", errors="replace")
    if rc != 0:
        raise DockerFailure(
            "docker images fallback failed",
            {"return_code": rc, "stderr": stderr_text},
        )
    candidates = [line.strip() for line in stdout_bytes.decode("utf-8", errors="replace").splitlines() if line.strip()]
    for candidate in candidates:
        if candidate == expected:
            return candidate
    return None


