_OCI_TAR_MAGIC_SIGNATURES = (b"manifest.json", b"oci-layout")


async def validate_image_archive(path: Path) -> None:
    def _read_head() -> bytes:
        with path.open("rb") as fh:
            return fh.read(65536)
    head = await asyncio.to_thread(_read_head)
    if not head:
        raise DockerFailure("Image archive is empty", {"path": str(path)})
    if not any(signature in head for signature in _OCI_TAR_MAGIC_SIGNATURES):
        if head[257:262] != b"ustar":
            raise DockerFailure(
                "Image archive does not appear to be an OCI/Docker tar archive",
                {"path": str(path)},
            )


async def copy_path_streamed(source: Path, destination: Path, *, recursive_ok: bool) -> None:
    def _copy() -> None:
        destination.parent.mkdir(parents=True, exist_ok=True)
        if source.is_dir():
            if not recursive_ok:
                raise DockerFailure(
                    "Refusing to copy directory without recursive permission",
                    {"source": str(source), "destination": str(destination)},
                )
            if destination.exists():
                shutil.rmtree(destination)
            shutil.copytree(source, destination, copy_function=shutil.copy2)
        else:
            shutil.copy2(source, destination)
    await asyncio.to_thread(_copy)


async def _retrying_request(
    client: httpx.AsyncClient,
    method: str,
    url: str,
    *,
    headers: Dict[str, str],
    json_body: Optional[Dict[str, Any]] = None,
    idempotent: bool = True,
) -> httpx.Response:
    last_exc: Optional[BaseException] = None
    max_retries = INSTAVM_HTTP_MAX_RETRIES if idempotent else 0
    for attempt in range(max_retries + 1):
        try:
            response = await client.request(method, url, headers=headers, json=json_body)
            if response.status_code >= 500 and idempotent and attempt < max_retries:
                await asyncio.sleep(min(2.0 * (attempt + 1), 10.0))
                continue
            return response
        except (httpx.RequestError, httpx.HTTPError) as exc:
            last_exc = exc
            if attempt >= max_retries:
                break
            await asyncio.sleep(min(2.0 * (attempt + 1), 10.0))
    raise InstaVMFailure(
        f"InstaVM HTTP {method} {url} failed after retries: {last_exc!r}",
        details={"method": method, "url": url, "exception": repr(last_exc)},
    )


def _ensure_dict(value: Any, where: str) -> Dict[str, Any]:
    if not isinstance(value, dict):
        raise InstaVMFailure(
            f"InstaVM response field {where!r} is not an object",
            details={"value": json_safe(value)},
        )
    return value


def _classify_instavm_status_code(status_code: int, context: str) -> int:
    if status_code == 401 or status_code == 403:
        return 502
    if status_code == 404:
        return 404
    if status_code == 422:
        return 502
    if 400 <= status_code < 500:
        return 502
    return 502


