def _parse_positive_float(env_name: str, default: float) -> float:
    raw = os.environ.get(env_name)
    if raw is None or raw == "":
        return default
    try:
        value = float(raw)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"Environment variable {env_name} must be a number, got {raw!r}") from exc
    if not math.isfinite(value) or value <= 0:
        raise RuntimeError(f"Environment variable {env_name} must be a positive finite number, got {value!r}")
    return value


def _parse_positive_int(env_name: str, default: int) -> int:
    raw = os.environ.get(env_name)
    if raw is None or raw == "":
        return default
    try:
        value = int(raw)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"Environment variable {env_name} must be an integer, got {raw!r}") from exc
    if value <= 0:
        raise RuntimeError(f"Environment variable {env_name} must be a positive integer, got {value!r}")
    return value


def _parse_nonneg_int(env_name: str, default: int) -> int:
    raw = os.environ.get(env_name)
    if raw is None or raw == "":
        return default
    try:
        value = int(raw)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"Environment variable {env_name} must be an integer, got {raw!r}") from exc
    if value < 0:
        raise RuntimeError(f"Environment variable {env_name} must be a non-negative integer, got {value!r}")
    return value


