def _resolve_tasks_root() -> Path:
    raw = os.environ.get("TASKS_ROOT", str(Path.cwd() / "tasks"))
    candidate = Path(raw).expanduser().resolve()
    try:
        candidate.mkdir(parents=True, exist_ok=True)
        probe = candidate / f".write-probe-{uuid.uuid4().hex}"
        probe.write_text("ok", encoding="utf-8")
        probe.unlink()
    except OSError as exc:
        raise RuntimeError(f"TASKS_ROOT {candidate!s} is not writable: {exc}") from exc
    return candidate


