class NixRefreshRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")

    flakeNix: str = Field(min_length=1)
    dockerfile: Optional[str] = None
    imageName: str = Field(min_length=1)
    imageTag: str = Field(min_length=1)
    registry: Optional[str] = None
    repository: Optional[str] = None
    snapshotName: Optional[str] = None
    snapshotType: str = Field(default="user", pattern=r"^(user|system)$")
    cpu: int = Field(default=2, ge=1, le=8)
    memoryMb: int = Field(default=512, ge=128, le=8192)
    diskGb: Optional[int] = Field(default=None, ge=1, le=16)
    push: bool = True
    nixBuildArgs: Optional[Dict[str, str]] = None
    instavmBuildArgs: Optional[NixBuildArgs] = None
    envs: Optional[Dict[str, str]] = None
    postBuildCmd: Optional[str] = None
    flakeFileName: str = Field(default="flake.nix")
    dockerFileName: Optional[str] = None
    taskId: Optional[str] = None
    runInBackground: bool = True
    requireDigestReference: bool = False

    @field_validator("flakeNix")
    @classmethod
    def _validate_flake_syntax(cls, value: str) -> str:
        if "{" not in value or "}" not in value:
            raise ValueError("flakeNix does not look like a Nix flake (missing braces)")
        if "outputs" not in value:
            raise ValueError("flakeNix does not contain an 'outputs' definition")
        return value

    @field_validator("flakeFileName")
    @classmethod
    def _enforce_flake_filename(cls, value: str) -> str:
        if value != "flake.nix":
            raise ValueError("flakeFileName must be exactly 'flake.nix' for nix flake builds")
        return value

    @field_validator("dockerFileName")
    @classmethod
    def _validate_dockerfile_name(cls, value: Optional[str]) -> Optional[str]:
        if value is None:
            return value
        if not re.fullmatch(r"(?i)dockerfile(\.[A-Za-z0-9._-]+)?", value):
            raise ValueError("dockerFileName must match Dockerfile or Dockerfile.<ext>")
        return value

    @field_validator("imageTag")
    @classmethod
    def _validate_image_tag(cls, value: str) -> str:
        if not _DOCKER_TAG_RE.match(value):
            raise ValueError(f"Invalid Docker tag: {value!r}")
        if value == "latest":
            return value
        return value


